 "content": "def transform(grid):
    # Count isolated T tetrominoes: stems above the bar are encoded as 3,
    # stems below as 1. Encode each count in the four corners, in order
    # top-left, bottom-left, top-right, bottom-right.
    h, w = len(grid), len(grid[0])
    seen = set()
    up = down = 0
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y+dy, x+dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 2 and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            if len(comp) == 4:
                rows = {}
                for y, x in comp:
                    rows.setdefault(y, set()).add(x)
                bar = next((y for y, xs in rows.items() if len(xs) == 3), None)
                if bar is None:
                    continue
                stem_row = next(y for y, xs in rows.items() if len(xs) == 1)
                if stem_row < bar:
                    up += 1
                else:
                    down += 1
    out = [[0]*6 for _ in range(3)]
    positions = ((0,0), (2,0), (0,2), (2,2))
    for n, color, offset in ((up, 3, 0), (down, 1, 3)):
        for i in range(min(n, 4)):
            y, x = positions[i]
            out[y][offset+x] = color
    return out
